import { useEffect, useState, type RefObject } from "react";

/**
 * Whether the book is wide enough to show two leaves side by side.
 *
 * StPageFlip decides this internally and only announces it after the book has
 * been built, which is too late for anything that has to change the page list
 * the book is built from. The rule it applies to a stretched book is simply
 * whether two leaves clear their minimum width, so it is reproduced here
 * against the same host element and the same threshold.
 *
 * Starts as false so the first paint on a narrow screen never flashes a spacer
 * page that a phone would then have to flip past.
 */
export function useSpreads(
  hostRef: RefObject<HTMLElement | null>,
  minWidth: number,
): boolean {
  const [spreads, setSpreads] = useState(false);

  useEffect(() => {
    const host = hostRef.current;
    if (!host) return;

    const observer = new ResizeObserver(([entry]) => {
      setSpreads(entry.contentRect.width >= minWidth);
    });
    observer.observe(host);

    return () => observer.disconnect();
  }, [hostRef, minWidth]);

  return spreads;
}
